const PROFILE_ID=new URLSearchParams(location.search).get('profile')||'default';
const LOCAL_BRIDGE=['localhost','127.0.0.1'].includes(location.hostname)?'':'http://127.0.0.1:4173';let codexConnected=false;
const KEY='resume-tailor-v2:'+PROFILE_ID;
const defaults={profile:{name:'',target:'',phone:'',email:'',age:'',location:'',degree:'',selfEvaluation:'',gameExperience:'',education:'',skills:'',experiences:[],customSections:[]},job:{company:'',jobTitle:'',jobUrl:'',jdText:''},prefs:{tone:'直接、克制、专业',length:'2',provider:'codex-local',apiEndpoint:'',modelName:'',apiKey:''},resumes:[],activeResumeId:null,logs:[]};
let state=load();
function merge(a,b){if(Array.isArray(a))return Array.isArray(b)?b:a;const o={...a};Object.keys(b||{}).forEach(k=>o[k]=a[k]&&typeof a[k]==='object'&&!Array.isArray(a[k])?merge(a[k],b[k]):b[k]);return o}
function load(){try{const registry=JSON.parse(localStorage.getItem('resume-tailor-profiles')||'[]'),person=registry.find(x=>x.id===PROFILE_ID);const legacy=PROFILE_ID==='default'?(localStorage.getItem('resume-tailor-v2')||localStorage.getItem('resume-tailor-v1')):null;const out=merge(defaults,JSON.parse(localStorage.getItem(KEY)||legacy||'{}'));if(person&&!out.profile.name)out.profile={...out.profile,...person.basics};return out}catch{return structuredClone(defaults)}}
function save(){localStorage.setItem(KEY,JSON.stringify(state));document.querySelector('#saveState').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});updateCompleteness()}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function fieldScope(k){return k in state.profile?state.profile:k in state.job?state.job:state.prefs}
document.querySelectorAll('[data-field]').forEach(el=>{const s=fieldScope(el.dataset.field);el.value=s[el.dataset.field]||'';el.addEventListener('input',()=>{s[el.dataset.field]=el.value;save();if(el.dataset.field==='jdText')summarizeJd()})});
function go(id){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id==='panel-'+id));document.querySelectorAll('.steps button').forEach(x=>x.classList.toggle('active',x.dataset.panel===id));document.querySelector('.workspace').scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('.steps button').forEach(b=>b.onclick=()=>go(b.dataset.panel));
function updateCompleteness(){const p=state.profile;const vals=[p.name,p.email,p.age,p.location,p.degree,state.originalResume?.text,state.job.jdText];document.querySelector('#completeness').textContent=Math.round(vals.filter(v=>String(v||'').trim()).length/7*100)+'%'}
function renderExperiences(){const root=document.querySelector('#experienceList');root.innerHTML='';state.profile.experiences.forEach((x,i)=>{const card=document.createElement('div');card.className='experience-card';card.innerHTML=`<div class="experience-actions"><button data-move="up" ${i===0?'disabled':''}>↑ 上移</button><button data-move="down" ${i===state.profile.experiences.length-1?'disabled':''}>↓ 下移</button><button data-delete aria-label="删除经历">删除</button></div><div class="experience-order">第 ${i+1} 项 · 生成时按此顺序</div><div class="row"><label>项目 / 公司<input data-x="title" value="${esc(x.title)}" placeholder="名称"></label><label>角色<input data-x="role" value="${esc(x.role)}" placeholder="你的角色"></label><label>时间<input data-x="date" value="${esc(x.date)}" placeholder="2024.03 - 至今"></label></div><label class="wide">事实与成果<textarea data-x="details" rows="5" placeholder="每行一条。写清动作、对象、方法、可验证结果。">${esc(x.details)}</textarea></label>`;card.querySelector('[data-delete]').onclick=()=>{state.profile.experiences.splice(i,1);save();renderExperiences()};card.querySelectorAll('[data-move]').forEach(button=>button.onclick=()=>{const next=button.dataset.move==='up'?i-1:i+1;if(next<0||next>=state.profile.experiences.length)return;[state.profile.experiences[i],state.profile.experiences[next]]=[state.profile.experiences[next],state.profile.experiences[i]];save();renderExperiences();document.querySelectorAll('.experience-card')[next]?.scrollIntoView({behavior:'smooth',block:'center'});toast('经历顺序已调整并保存')});card.querySelectorAll('[data-x]').forEach(el=>el.oninput=()=>{x[el.dataset.x]=el.value;save()});root.append(card)});if(!state.profile.experiences.length)root.innerHTML='<div class="empty-note">还没有经历。可以添加工作、项目、研究、账号运营或社群经历。</div>'}
document.querySelector('#addExperience').onclick=()=>{state.profile.experiences.push({title:'',role:'',date:'',details:''});save();renderExperiences()};
function renderCustomSections(){const root=document.querySelector('#customSectionList');root.innerHTML='';state.profile.customSections=state.profile.customSections||[];state.profile.customSections.forEach((x,i)=>{const card=document.createElement('div');card.className='experience-card';card.innerHTML=`<button aria-label="删除栏目">删除</button><label>栏目名称<input data-custom="title" value="${esc(x.title)}" placeholder="例如：证书 / 获奖 / 作品"></label><label class="wide">原始事实<textarea data-custom="content" rows="4" placeholder="只写可确认的事实，生成时由 AI 润色。">${esc(x.content)}</textarea></label>`;card.querySelector('button').onclick=()=>{state.profile.customSections.splice(i,1);save();renderCustomSections()};card.querySelectorAll('[data-custom]').forEach(el=>el.oninput=()=>{x[el.dataset.custom]=el.value;save()});root.append(card)});if(!state.profile.customSections.length)root.innerHTML='<div class="empty-note">模板外内容不会默认出现；确实需要时再手动添加。</div>'}
document.querySelector('#addCustomSection').onclick=()=>{state.profile.customSections.push({title:'',content:''});save();renderCustomSections()};
const stop=new Set('负责 相关 进行 完成 工作 能力 经验 要求 岗位 具备 熟悉 优先 以及 通过 根据 可以 良好 以上 我们 职责 任职'.split(' '));
function words(){const chunks=state.job.jdText.match(/[\u4e00-\u9fa5]{2,8}|[A-Za-z][A-Za-z0-9+#.]{1,}/g)||[],count={};chunks.forEach(w=>{w=w.toLowerCase();if(!stop.has(w)&&w.length>1)count[w]=(count[w]||0)+1});return Object.entries(count).sort((a,b)=>b[1]-a[1]).slice(0,12).map(x=>x[0])}
function summarizeJd(){const ks=words(),el=document.querySelector('#jdSummary');el.innerHTML=state.job.jdText.trim().length<30?'<div><b>等待分析</b><span>粘贴至少 30 个字后，将自动提取岗位关键词。</span></div>':`<div><b>已识别 ${ks.length} 个重点</b><span>${ks.slice(0,7).join(' · ')}</span></div>`}
function corpus(){return[state.profile.selfEvaluation,state.profile.gameExperience,state.profile.education,state.profile.skills,...state.profile.experiences.map(x=>Object.values(x).join(' ')),...(state.profile.customSections||[]).map(x=>Object.values(x).join(' '))].join(' ').toLowerCase()}
function renderFit(){const ks=words(),c=corpus(),m=ks.filter(k=>c.includes(k));document.querySelector('#fitScore').textContent=(ks.length?Math.round(m.length/ks.length*100):0)+'%';document.querySelector('#keywords').innerHTML=ks.map(k=>`<span class="chip">${esc(k)}${m.includes(k)?' ✓':''}</span>`).join('')||'<span>尚未提取到关键词</span>'}
document.querySelector('#analyzeJd').onclick=()=>{if(state.job.jdText.trim().length<30)return toast('请先粘贴完整 JD');renderFit();go('generate')};
const bullets=s=>String(s||'').split(/\n|；/).map(x=>x.trim()).filter(Boolean);
function generateLocalHtml(){const p=state.profile,j=state.job,ks=words(),c=corpus();const relevant=p.experiences.map(x=>({...x,score:ks.filter(k=>Object.values(x).join(' ').toLowerCase().includes(k)).length})).sort((a,b)=>b.score-a.score);const summary=p.positioning||`${p.target||'目标岗位'}候选人，具备与内容、用户和项目推进相关的实践经验。`;const exp=relevant.map(x=>`<div class="resume-item"><header><h4>${esc(x.title||'未命名经历')}｜${esc(x.role||'')}</h4><span>${esc(x.date||'')}</span></header><ul>${bullets(x.details).map(b=>`<li>${esc(b)}</li>`).join('')||'<li>待补充可验证的职责与成果</li>'}</ul></div>`).join('');document.querySelector('#resumePaper').innerHTML=`<div class="resume-head"><div class="resume-namebar"><div class="resume-name">${esc(p.name||'你的姓名')}</div><div class="resume-target">意向岗位：${esc(j.jobTitle||p.target||'请填写目标岗位')}${j.company?'｜'+esc(j.company):''}</div></div><div class="resume-contact"><span>电话：${esc(p.phone||'待填写')}</span><span>邮箱：${esc(p.email||'待填写')}</span><span>现所在地：${esc(p.location||'待填写')}</span><span>最高学历：${esc(p.degree||'待填写')}</span></div></div><div class="resume-body"><section class="resume-section"><h3><span>职业概述</span></h3><p>${esc(summary)}</p></section><section class="resume-section"><h3><span>核心匹配</span></h3><p>${ks.filter(k=>c.includes(k)).slice(0,8).join(' ｜ ')||'待补充与岗位相关的能力证据'}</p></section><section class="resume-section"><h3><span>经历</span></h3>${exp||'<p>请先在资料库添加经历。</p>'}</section><section class="resume-section"><h3><span>教育经历</span></h3>${bullets(p.education).map(x=>`<p>${esc(x)}</p>`).join('')||'<p>待填写</p>'}</section><section class="resume-section"><h3><span>相关技能</span></h3>${bullets(p.skills).map(x=>`<p>${esc(x)}</p>`).join('')||'<p>待填写</p>'}</section></div>`;state.logs.push({time:new Date().toISOString(),event:'resume_generated',job:j.jobTitle||'',keywords:ks.length});state.logs=state.logs.slice(-30);save();document.querySelector('#generationNote').textContent='已按岗位关键词重新排序。请在预览页逐字确认。';go('preview')}
async function generate(){generateLocalHtml();if(state.prefs.provider!=='codex-local')return toast('已生成本地规则版本');const prior=state.resumes.find(x=>x.id===state.activeResumeId);try{toast('本机 Codex 正在整理内容…');const r=await fetch('/api/codex/rewrite',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({profile:state.profile,job:state.job,priorResume:prior?{title:prior.title,text:prior.text}:null,tone:state.prefs.tone})});const d=await r.json();if(!r.ok)throw new Error(d.error||'调用失败');document.querySelector('#resumePaper').innerHTML=d.html;toast('Codex 已根据保存内容完成修改')}catch(e){state.logs.push({time:new Date().toISOString(),event:'codex_error',message:e.message});save();toast('已保留本地版本；Codex：'+e.message)}}
document.querySelector('#generateResume').onclick=generate;document.querySelector('#printResume').onclick=()=>window.print();document.querySelector('#copyResume').onclick=async()=>{await navigator.clipboard.writeText(document.querySelector('#resumePaper').innerText);toast('已复制简历全文')};
const providers=[['codex-local','本机 Codex','自动连接'],['deepseek','DeepSeek','OpenAI-compatible'],['doubao','豆包','火山引擎'],['gemini','Gemini','Google AI']];
function aiInput(){return{profile:state.profile,originalResume:state.originalResume||null,portfolio:state.portfolio||null,job:state.job,tone:state.prefs.tone}}
function resumeAiPrompt(){const analysis=state.job.analysis||window.analyzeCareerJob?.()||{};return`你是跨行业简历策略编辑。请完成“JD分析→证据映射→内容策略→真实改写→ATS检查→去AI味检查”，而不是复制原文，也不要输出分析过程。
事实边界来自原始简历、作品集和个人资料：不得编造公司、学校、时间、职责、数字、技能、工具、项目或成果；不得把参与写成主导；相近经验只能按事实描述，不能冒充直接经验。岗位分析中的无证据项必须排除。
通用改写规则：
1. 根据岗位类型使用该行业真实语言；内容/品牌强调受众、渠道、传播和转化，产品/项目强调问题、决策、推进和结果，销售/客户成功强调客户、管线、成交和续约，技术/数据强调系统、工具、规模和结果，设计强调问题、过程、交付和用户结果，教育/研究强调课程、研究、对象和成果，其他职业遵循动作→对象→方法→结果。
2. 自我评价必须针对当前JD重写，只写下文能够证明的事实；禁止“赋能、深耕、抓手、闭环、卓越、充满热情、结果导向、拥有丰富经验、具备较强能力”等套话。
3. 输入中的每一份经历都必须独立呈现，不得整段遗漏；经历顺序严格按照 profile.experiences 数组顺序，不得自行重排；可以压缩，但必须保留公司/项目、角色、时间及至少一条真实事实。每条先写最有价值的动作或结果，句式长短要有变化。
4. 数字只能使用资料中已有数字。没有数字时写可核实的范围、交付物、对象、流程变化或非数字结果，不得虚构百分比。
5. 教育、技能和用户自定义栏目按JD筛选、排序和改写；技能只保留资料中出现且能解释的内容。不要擅自增加栏目。
6. 自检：有事实支持的JD关键词自然出现；无证据关键词不得出现；不用关键词堆砌；不得连续三条使用同一开头；不用“负责、协助、参与”掩盖具体动作，但事实确为参与时必须诚实保留。
7. 只返回可放入article的HTML片段，不要Markdown、script或style。每份经历必须使用独立的.resume-item，保留class：resume-head、resume-namebar、resume-name、resume-target、resume-contact、resume-body、resume-section、resume-item。
岗位分析与证据映射：${JSON.stringify(analysis)}
输入JSON：\n${JSON.stringify(aiInput())}`}
function sanitizeResumeHtml(html){const box=document.createElement('div');box.innerHTML=String(html||'').replace(/^```html\s*|\s*```$/g,'');box.querySelectorAll('script,style,iframe').forEach(x=>x.remove());box.querySelectorAll('.resume-section').forEach(section=>{const heading=section.querySelector('h3 span,h3')?.textContent.trim()||'';if(/核心匹配|岗位匹配/.test(heading)){section.remove();return}if(/职业概述/.test(heading)){const target=section.querySelector('h3 span')||section.querySelector('h3');if(target)target.textContent='自我评价'}if(/^(经历|相关经历)$/.test(heading)){const target=section.querySelector('h3 span')||section.querySelector('h3');if(target)target.textContent='项目 / 工作经历'}});box.querySelectorAll('li').forEach(li=>{li.textContent=li.textContent.replace(/^[\s•·●▪◦\-]+/,'').trim();if(!li.textContent)li.remove()});box.querySelectorAll('p').forEach(p=>p.textContent=p.textContent.replace(/^[\s•·●▪◦]+/,'').trim());return box.innerHTML}
async function callConfiguredModel(){const endpoint=state.prefs.apiEndpoint.trim(),model=state.prefs.modelName.trim(),key=state.prefs.apiKey.trim();if(!endpoint||!model||!key)throw new Error('请先在“模型设置”填写接口地址、模型名称和 API Key');const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+key},body:JSON.stringify({model,messages:[{role:'system',content:'你是严谨的中文简历编辑，只能改写明确存在的事实。'},{role:'user',content:resumeAiPrompt()}],temperature:.35})});const type=r.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('模型接口没有返回JSON，请检查接口地址或浏览器跨域限制');const d=await r.json();if(!r.ok)throw new Error(d.error?.message||d.message||'模型调用失败');const html=d.choices?.[0]?.message?.content;if(!html)throw new Error('模型没有返回简历内容');return String(html).replace(/^```html\s*|\s*```$/g,'')}
const providerDefaults={deepseek:{apiEndpoint:'https://api.deepseek.com/chat/completions',modelName:'deepseek-flash'},doubao:{apiEndpoint:'https://ark.cn-beijing.volces.com/api/v3/chat/completions',modelName:'doubao-seed-2-1-pro-260915'},gemini:{apiEndpoint:'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',modelName:'gemini-2.5-flash'}};
function providerHelp(){const help=document.querySelector('#providerHelp');if(!help)return;if(state.prefs.provider==='codex-local')help.textContent=codexConnected?'Codex 已自动连接本机，可直接生成。':'本机服务未启动。请双击“启动简历工坊.command”，保持窗口运行后点击重新检测。';else if(state.prefs.provider==='deepseek')help.textContent='需要 DeepSeek API Key。DeepSeek 网页聊天免费，但 API 按 token 计费。';else if(state.prefs.provider==='doubao')help.textContent='需要火山方舟 API Key；新用户可能有免费推理额度，额度用完会暂停或计费。';else help.textContent='需要 Google AI Studio API Key；是否有免费额度以账号所在地区和控制台显示为准。'}
function renderProviders(){document.querySelector('#providers').innerHTML=providers.map(x=>`<button class="provider ${state.prefs.provider===x[0]?'active':''}" data-p="${x[0]}"><b>${x[1]}</b><small>${x[2]}</small></button>`).join('');document.querySelectorAll('.provider').forEach(b=>b.onclick=()=>{state.prefs.provider=b.dataset.p;if(providerDefaults[b.dataset.p]){state.prefs.apiEndpoint=providerDefaults[b.dataset.p].apiEndpoint;state.prefs.modelName=providerDefaults[b.dataset.p].modelName;document.querySelector('[data-field="apiEndpoint"]').value=state.prefs.apiEndpoint;document.querySelector('[data-field="modelName"]').value=state.prefs.modelName}save();renderProviders();providerHelp()});providerHelp()}
async function detectCodex(){const box=document.querySelector('#localStatus');codexConnected=false;try{const r=await fetch(LOCAL_BRIDGE+'/api/codex/health');if(!r.ok||!(r.headers.get('content-type')||'').includes('application/json'))throw new Error();const d=await r.json();codexConnected=true;box.className='local-status connected';box.querySelector('b').textContent='本机 Codex 已连接';box.querySelector('span').textContent=d.version+' · 会真实调用 Codex 改写';state.prefs.provider='codex-local';save();renderProviders()}catch{box.className='local-status error';box.querySelector('b').textContent='本机 Codex 未连接';box.querySelector('span').textContent='公网版需先启动本机桥接，或选择 DeepSeek / 豆包 / Gemini 并填写接口配置'}}
async function testModelConnection(){if(state.prefs.provider==='codex-local'){await detectCodex();return toast(codexConnected?'Codex 连接成功':'Codex 未连接：本机 4173 服务没有运行')}const endpoint=state.prefs.apiEndpoint.trim(),model=state.prefs.modelName.trim(),key=state.prefs.apiKey.trim();if(!endpoint||!model||!key)return toast('请填写接口地址、模型名称和 API Key');try{toast('正在发送真实测试请求…');const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+key},body:JSON.stringify({model,messages:[{role:'user',content:'只回复：连接成功'}],max_tokens:20})});const type=r.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('接口未返回JSON，可能被浏览器跨域策略拦截');const d=await r.json();if(!r.ok)throw new Error(d.error?.message||d.message||'连接失败');if(!d.choices?.[0]?.message?.content)throw new Error('接口返回格式不兼容');toast(`${providers.find(x=>x[0]===state.prefs.provider)?.[1]||'模型'}连接成功`)}catch(e){state.logs.push({time:new Date().toISOString(),event:'model_connection_error',provider:state.prefs.provider,message:e.message});save();toast('连接失败：'+e.message)}}
const aiSettingsDialog=document.querySelector('#aiSettingsDialog');document.querySelector('#openAISettings').onclick=()=>{aiSettingsDialog.showModal();detectCodex()};document.querySelector('.close-ai-settings').onclick=()=>aiSettingsDialog.close();aiSettingsDialog.addEventListener('click',e=>{if(e.target===aiSettingsDialog)aiSettingsDialog.close()});document.querySelector('#detectCodex').onclick=detectCodex;document.querySelector('#testConnection').onclick=testModelConnection;
function saveResumeVersion(){const paper=document.querySelector('#resumePaper');if(!paper.innerText.trim())generateLocalHtml();const now=new Date(),id='resume_'+Date.now();state.resumes.unshift({id,title:(state.job.jobTitle||state.profile.target||'未命名岗位')+' · '+now.toLocaleDateString('zh-CN'),company:state.job.company||'',jobTitle:state.job.jobTitle||state.profile.target||'',createdAt:now.toISOString(),html:paper.innerHTML,text:paper.innerText,job:structuredClone(state.job)});state.activeResumeId=id;save();renderLibrary();toast('已保存到简历库')}
function renderLibrary(filter=''){const list=document.querySelector('#libraryList'),q=filter.trim().toLowerCase();const items=state.resumes.filter(x=>[x.title,x.company,x.jobTitle,x.text].join(' ').toLowerCase().includes(q));document.querySelector('#libraryCount').textContent=state.resumes.length;list.innerHTML=items.length?items.map(x=>`<div class="library-item"><div><h3>${esc(x.title)}</h3><p><span class="tag">${esc(x.jobTitle||'未标岗位')}</span>${x.company?'<span class="tag">'+esc(x.company)+'</span>':''}</p><p>保存于 ${new Date(x.createdAt).toLocaleString('zh-CN')} · ${x.text.length} 字${state.activeResumeId===x.id?' · 当前改写基础':''}</p></div><div class="library-actions"><button data-open="${x.id}">打开</button><button data-base="${x.id}">设为改写基础</button><button class="danger" data-del="${x.id}">删除</button></div></div>`).join(''):'<div class="library-empty">还没有保存的简历版本。生成后点击“保存到简历库”。</div>';list.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const x=state.resumes.find(v=>v.id===b.dataset.open);document.querySelector('#resumePaper').innerHTML=x.html;state.activeResumeId=x.id;state.job=merge(state.job,x.job||{});save();document.querySelector('#resumeLibrary').close();go('preview');toast('已打开历史简历')});list.querySelectorAll('[data-base]').forEach(b=>b.onclick=()=>{state.activeResumeId=b.dataset.base;save();renderLibrary(q);toast('已设为 Codex 改写基础')});list.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{if(!confirm('确定删除这个简历版本吗？'))return;state.resumes=state.resumes.filter(v=>v.id!==b.dataset.del);if(state.activeResumeId===b.dataset.del)state.activeResumeId=null;save();renderLibrary(q)})}
const dialog=document.querySelector('#resumeLibrary');document.querySelector('#openLibrary').onclick=()=>{renderLibrary();dialog.showModal()};document.querySelector('.close-dialog').onclick=()=>dialog.close();document.querySelector('#saveResume').onclick=saveResumeVersion;document.querySelector('#saveFromLibrary').onclick=saveResumeVersion;document.querySelector('#librarySearch').oninput=e=>renderLibrary(e.target.value);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
function report(){return{app:'简历定向工坊',version:'0.3.0',generatedAt:new Date().toISOString(),page:location.href,userAgent:navigator.userAgent,lastActions:state.logs.slice(-10),dataSummary:{experienceCount:state.profile.experiences.length,resumeCount:state.resumes.length,jdLength:state.job.jdText.length,provider:state.prefs.provider},privacy:{fileUpload:'browser-only',temporaryFiles:'released after parsing'},secretsExcluded:['apiKey','resumeText','personalFacts'],reproduction:'请填写：点击了什么、期待什么、实际发生什么。'}}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
document.querySelector('#downloadReport').onclick=()=>download('简历定向工坊-错误报告-'+Date.now()+'.json',JSON.stringify(report(),null,2));document.querySelector('#simulateError').onclick=()=>alert(JSON.stringify(report(),null,2));document.querySelector('#exportBackup').onclick=()=>{const safe=structuredClone(state);safe.prefs.apiKey='';download('简历资料与历史-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(safe,null,2));toast('资料和历史已导出（不含 API Key）')};
document.querySelector('#clearProfileData').onclick=()=>{if(!confirm('确定清除当前人员的事实资料、原版简历、岗位和历史版本吗？清除后无法恢复，建议先导出备份。'))return;localStorage.removeItem(KEY);location.reload()};
window.addEventListener('error',e=>{state.logs.push({time:new Date().toISOString(),event:'error',message:e.message,source:e.filename,line:e.lineno});state.logs=state.logs.slice(-30);save()});
renderExperiences();renderCustomSections();renderProviders();renderLibrary();summarizeJd();updateCompleteness();detectCodex();if(state.profile.name||state.profile.experiences.length)generateLocalHtml();
